  int32_t kind;
  int32_t epoch;
  int32_t obsolete_epoch;
  int32_t research_delay;
  int32_t prerequisites[4];
  uint8_t prerequisite_flags;
  bool researched;
  /// `mIsObsolete` (the flag; [`node_is_obsolete`] adds the obsolete epoch)
  bool obsolete;
