struct EeTechSumCostsCallbacks {
  void *ctx;
  bool (*node)(void *ctx, int32_t id, EeTechSumNode *out);
  int32_t (*cost)(void *ctx, int32_t id, int32_t resource, int32_t unit_class);
  int32_t (*class_technology)(void *ctx, int32_t unit_class);
};

